node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createShop } from './src/index.mjs';

const initial = { red: { a: 5, b: 2 }, blue: { a: 4 } };
const shop = createShop(initial);
initial.red.a = 99;
assert.equal(shop.stock('red', 'a'), 5);
const items = [{ sku: 'b', quantity: 1 }, { sku: 'a', quantity: 1 }, { sku: 'a', quantity: 2 }];
const receipt = shop.reserve({ tenant: 'red', requestId: 'same', items });
assert.deepEqual(receipt.items, [{ sku: 'a', quantity: 3 }, { sku: 'b', quantity: 1 }]);
items[0].quantity = 2;
receipt.items[0].quantity = 100;
assert.equal(shop.stock('red', 'a'), 2);
assert.equal(shop.stock('red', 'b'), 1);
assert.deepEqual(shop.reserve({ tenant: 'red', requestId: 'same', items: [{ sku: 'a', quantity: 1 }, { sku: 'b', quantity: 1 }, { sku: 'a', quantity: 2 }] }).items,
  [{ sku: 'a', quantity: 3 }, { sku: 'b', quantity: 1 }]);
shop.reserve({ tenant: 'blue', requestId: 'same', items: [{ sku: 'a', quantity: 1 }] });
assert.equal(shop.stock('blue', 'a'), 3);
assert.throws(() => shop.reserve({ tenant: 'red', requestId: 'same', items: [{ sku: 'a', quantity: 2 }] }), /Conflicting request/);
assert.equal(shop.stock('red', 'a'), 2);
assert.throws(() => shop.reserve({ tenant: 'red', requestId: 'failed', items: [{ sku: 'a', quantity: 2 }, { sku: 'missing', quantity: 1 }] }));
assert.equal(shop.stock('red', 'a'), 2);
shop.reserve({ tenant: 'red', requestId: 'failed', items: [{ sku: 'a', quantity: 2 }] });
assert.equal(shop.stock('red', 'a'), 0);
console.log('additional reservation checks passed');
EOF

